        // ---------------------------------------------------------------------
        // The dog's rig description, written by build_dog.py next to the model
        // ---------------------------------------------------------------------
        struct EyeDesc
        {
            std::string Bone;
            glm::vec3 Centre{ 0.0f };
            glm::vec3 Gaze{ 0.0f, 0.0f, 1.0f };
            glm::vec3 Up{ 0.0f, 1.0f, 0.0f };
        };
        struct RigDesc
        {
            f32 EyeRadius = 0.0f;
            f32 SocketRadius = 0.0f;
            std::array<EyeDesc, 2> Eyes; // L, R
            bool Valid = false;
        };

        [[nodiscard]] glm::vec3 Vec3Of(const nlohmann::json& j)
        {
            return { j.at(0).get<f32>(), j.at(1).get<f32>(), j.at(2).get<f32>() };
        }

        [[nodiscard]] RigDesc ReadRig()
        {
            RigDesc rig;
            std::ifstream in(DogDir() / "Dog.rig.json");
            if (!in)
            {
                return rig;
            }
            const nlohmann::json j = nlohmann::json::parse(in, nullptr, false);
            if (j.is_discarded())
            {
                return rig;
            }
            rig.EyeRadius = j.value("eyeRadius", 0.0f);
            rig.SocketRadius = j.value("socketRadius", rig.EyeRadius * 1.15f);
            const char* sides[2] = { "L", "R" };
            for (u32 i = 0; i < 2u; ++i)
            {
                const auto& e = j.at("eyes").at(sides[i]);
                rig.Eyes[i].Bone = e.at("bone").get<std::string>();
                rig.Eyes[i].Centre = Vec3Of(e.at("centre"));
                rig.Eyes[i].Gaze = glm::normalize(Vec3Of(e.at("gaze")));
                rig.Eyes[i].Up = glm::normalize(Vec3Of(e.at("up")));
            }
            rig.Valid = rig.EyeRadius > 0.0f;
            return rig;
        }

        // OLO_DOG_REGION_DEBUG=1: build_dog_groom.py, run with it, paints each coat
